(function(root){
function createPool(){const items=[];return{items,spawn(text,x,y,kind='gain',enabled=true){if(!enabled)return false;if(items.length===12)items.shift();items.push({text,x,y,kind,life:1});return true},step(dt){for(const p of items){p.life-=dt;p.y-=dt*35}for(let i=items.length-1;i>=0;i--)if(items[i].life<=0)items.splice(i,1)}}}
const pool=createPool();let canvas,ctx,frame=0,last=0;
function enabled(){return !root.matchMedia?.('(prefers-reduced-motion: reduce)').matches&&root.ApexEffectsState?.()!=='off'}
function paint(now){const dt=last?Math.min(.05,(now-last)/1000):0;last=now;const ratio=Math.min(root.devicePixelRatio||1,2);if(canvas.width!==root.innerWidth*ratio)canvas.width=root.innerWidth*ratio;if(canvas.height!==root.innerHeight*ratio)canvas.height=root.innerHeight*ratio;ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,canvas.width,canvas.height);pool.step(dt);for(const p of pool.items){ctx.save();ctx.globalAlpha=p.life;ctx.strokeStyle=p.kind==='denied'?'#F0243E':'#FFB627';ctx.fillStyle=p.kind==='gain'?'#35E6A8':'#FFB627';ctx.lineWidth=2;ctx.beginPath();ctx.arc(p.x,p.y,8+(1-p.life)*32,0,Math.PI*2);ctx.stroke();ctx.font='bold 18px Hanken Grotesk';ctx.textAlign='center';ctx.fillText(p.text,p.x,p.y-20);ctx.restore()}if(pool.items.length)frame=root.requestAnimationFrame(paint);else{frame=0;last=0;ctx.clearRect(0,0,canvas.width,canvas.height)}}
function spawnFloat(text,x,y,kind='gain'){if(!enabled())return false;if(!canvas){canvas=root.document.createElement('canvas');canvas.className='v2-effects';canvas.setAttribute('aria-hidden','true');root.document.body.append(canvas);ctx=canvas.getContext('2d')}pool.spawn(text,x,y,kind);if(!frame)frame=root.requestAnimationFrame(paint);return true}
const api={createPool,pool,spawnFloat,ripple:(el,x,y)=>spawnFloat('',x,y,'ripple'),pulse:el=>{const r=el.getBoundingClientRect();spawnFloat('',r.x+r.width/2,r.y+r.height/2,'pulse')},shake:el=>{const r=el.getBoundingClientRect();spawnFloat('CR insuficiente',r.x+r.width/2,r.y,'denied')}};root.ApexEffects=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
